static const float X0 = 84.00;
static const float PITCH = 19.0000;
static const float Y = 1521.0;
static const float HALF = 20.0;
static const float R = 3.5;
static const float K0 = 0.0;
static const float KN = 15.0;
float4 shade(float2 pos, float px) {
    float i = clamp(round((pos.x - X0) / PITCH), 0.0, 48.0);
    float k = abs(i - 24.0);
    if (k < K0 || k >= K0 + KN) return float4(0.0, 0.0, 0.0, 0.0);
    float lv = saturate(param(int(k - K0))) * param(15);
    float h = lerp(HALF * 0.1, HALF, lv);
    float2 q = pos - float2(X0 + PITCH * i, clamp(pos.y, Y - h, Y + h));
    float cov = saturate(0.5 - (length(q) - R) / px);
    float u = k / 24.0;
    float3 c = lerp(srgb_to_linear(float3(0.557, 0.961, 0.710)), srgb_to_linear(float3(0.749, 0.890, 0.839)), u);
    float a = (1.0 - 0.75 * pow(u, 1.3)) * cov;
    return float4(c * a, a);
}

